LANGS = ["en", "es", "de"]
def gd(s):
    return json.dumps(s, ensure_ascii=False)
out = ["# Fichier généré par tools/translations.py — ne pas modifier à la main.", "const T := {"]
for i, code in enumerate(LANGS):
    out.append("\t%s: {" % gd(code))
    for k, v in T.items():
        out.append("\t\t%s: %s," % (gd(k), gd(v[i])))
    out.append("\t},")
out.append("}")
here = os.path.dirname(os.path.abspath(__file__))
open(os.path.join(here, "..", "scripts", "translations.gd"), "w").write("\n".join(out) + "\n")
print(len(T), "textes,", len(LANGS), "langues")
